      currentValue: '1',
      showPop: false,
      allwins: '',
      allnums: '',
      dataList: [{}, {}, {}, {}],
      typeList: [{ name: this.$t('wdsr.wdsr44'), value: '1' }, { name: this.$t('wdsr.wdsr45'), value: '2' }
      // , { name: '近7天', value: '7' }, { name: '近30天', value: '30' }
      ]
    }
  },
  created() {
    this.updateData()
  },
  methods: {
    async updateData() {
      const res = await winReport({ type: this.currentValue })
      this.allnums = res.allnums
      this.allwins = res.allwins
      this.dataList = res.datalist
    }
